#include <game/pxdvs/app/wazaSequence/boneFillPrivate.hpp>
void operator delete(void*);
struct GSpart;
extern "C" {GSpart*GSmodelGetPart(GSmodel*,s32);void GSpartFree(GSpart*);void GSpartGetTransform(GSpart*,GSvec*,GSvec*,GSvec*);_GSparticleGen*GSparticleCreateGenerator(_GSparticleBank*,u32,u32);void GSparticleDestroyGenerator(_GSparticleGen*,s32);u8 GSparticleIsGeneratorAlive(_GSparticleGen*);void GSparticleSetGeneratorPosition(_GSparticleGen*,GSvec*);void GSparticleSetGeneratorRotation(_GSparticleGen*,GSvec*);void GSparticleSetGeneratorScale(_GSparticleGen*,GSvec*,s32,s32);f32 PSVECMag(GSvec*);void PSVECScale(GSvec*,GSvec*,f32);void PSVECSubtract(GSvec*,GSvec*,GSvec*);double asin(double);double atan2(double,double);}
boneFillEffect::~boneFillEffect(){Stop();}
void boneFillEffect::_stop(){owner=0;if(generator){GSparticleDestroyGenerator(generator,1);generator=0;}}
bool boneFillEffect::_update(f32 dt){GSvec endpoints[2];GSvec scale;GSvec direction;GSvec rotation;GSvec difference;GSmodel*model;GSvec*endpoint;GSpart*part;s32 i;if(!owner)return false;if(!generator)return false;model=owner->model;if(!model)return false;if(!GSparticleIsGeneratorAlive(generator))return false;endpoint=endpoints;for(i=0;i<2;i++,endpoint++){part=GSmodelGetPart(model,bones[i]);if(!part)return false;GSpartGetTransform(part,endpoint,0,0);GSpartFree(part);}GSparticleSetGeneratorPosition(generator,endpoints);PSVECSubtract(endpoints+1,endpoints,&difference);direction.param1=difference.param1;direction.param2=difference.param2;direction.param3=difference.param3;f32 magnitude=PSVECMag(&direction);scale.param1=scale.param2=scale.param3=magnitude/length;GSparticleSetGeneratorScale(generator,&scale,0,0);if(magnitude>0.00001f){if(magnitude!=0.0f)PSVECScale(&direction,&direction,1.0f/magnitude);rotation.param1=-(f32)asin(direction.param2);rotation.param2=(f32)atan2(direction.param1,direction.param3);rotation.param3=0;GSparticleSetGeneratorRotation(generator,&rotation);}return true;}
bool boneFillEffect::_start(){if(!bank)return false;if(!owner)return false;if(!owner->model)return false;BoneModelCharacter*character=&owner->characters[owner->characterIndex];if(!character)return false;bones[0]=character->joints[first];if(bones[0]<0)return false;bones[1]=character->joints[second];if(bones[1]<0)return false;generator=GSparticleCreateGenerator(bank,0,0);if(generator)return _update(0.0f);return false;}
boneFillEffect::boneFillEffect(_GSparticleBank*b,enumNullJointName a,enumNullJointName z,f32 len){bank=b;generator=0;owner=0;length=len;first=a;second=z;}
